from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin
from mashumaro.helper import field_options
@dataclass
class Child(DataClassDictMixin):
    x: int
@dataclass
class Parent(DataClassDictMixin):
    child: Child = field(metadata=field_options(flatten=True))
p=Parent(Child(1))
print(p.to_dict()); print(Parent.from_dict({'x': 1}))
@dataclass
class OptionalParent(DataClassDictMixin):
    child: Optional[Child] = field(default=None, metadata=field_options(flatten=True, flatten_prefix=True))
print(OptionalParent(Child(1)).to_dict()); print(OptionalParent.from_dict({'child_x': 1})); print(OptionalParent.from_dict({}))
